/**
 * Where everything is in the pet's art.
 *
 * This is the contract between the drawing and the code. The drawing hits
 * these numbers, and the code reads them, so the two cannot quietly drift
 * apart — which is exactly what happened to the old hand-written hit region.
 *
 * Art contract v2: the pet is an 8-pixel-grid sprite, so everything the
 * anchors name is made of whole cells (a cell spans 8 art pixels). The
 * production art is generated by `scripts/build-pixel-mochi.mjs`, which
 * reads these numbers and draws the cells to match.
 */

/** The size of one grid cell, in the art's own units. */
export const CELL_SIZE = 8;

/** The artboard, in the art's own units. */
export const ART = {
  width: 200,
  height: 220,
  /** Where the pet's feet touch the ground: the bottom edge of the paws. */
  ground: 208,
  /** Where the contact shadow sits: the middle of the row under the feet. */
  shadow: 212,
  /** The character turns around this line. */
  centreX: 100,
} as const;

/**
 * The attachment points.
 *
 * Everything that can be added to the pet hangs off one of these, so a hat
 * always sits on the head and a mug always sits in the paw.
 */
export const ANCHORS = {
  /** The character's centre. */
  character: { x: 100, y: 140 },
  /** The head's centre, the middle of the two-cell-tall eyes. */
  head: { x: 100, y: 80 },
  /** The body's centre, where the belly is. */
  body: { x: 100, y: 160 },
  /** The scarf knot: the centre column of the band's second row. */
  scarfKnot: { x: 100, y: 128 },
  /** Where a hat perches, between the ears on the flat head top. */
  headAttach: { x: 100, y: 24 },
  /** The middle of the face, where glasses sit. */
  faceAttach: { x: 100, y: 78 },
  /** The right paw, where a mug is held. */
  pawAttach: { x: 153, y: 174 },
  /** The ground, where a bed would sit. */
  groundAttach: { x: 100, y: 212 },
  /** Where the tail leaves the body, the tail's wagging pivot. */
  tailRoot: { x: 148, y: 148 },
  /** The tip of the ears. */
  earTip: 8,
} as const;

/**
 * The colours the art is drawn in.
 *
 * These come from the design system's art palette, so the pet and the Den
 * are made of the same family of colours. It is a pixel-sprite palette:
 * every tone is one flat cell fill — no gradients — and the only in-between
 * tone in the whole art is the eye shine, cut into the ink at full strength.
 */
export const ART_PALETTE = {
  /** The line around everything. */
  ink: '#26160F',
  /** The fur itself. */
  body: '#F7C585',
  /** Highlights, eye shine, the near paws. */
  bodyLight: '#FFE9C4',
  /** The step between body and ink: far paws, shaded fur. */
  bodyShade: '#DF9E5B',
  /** The deepest tone: toes, whiskers. */
  bodyDeep: '#B97E42',
  /** The warm white inside the ink. */
  spark: '#FFF7EA',
  /** Inside the ears and on the cheeks. */
  innerEar: '#F6906E',
  /** The leaf hat and the moss scarf, in its two steps. */
  moss: '#7FA05E',
  mossDeep: '#5F8047',
  /** The sky scarf, in its two steps. */
  sky: '#6FA0D8',
  skyDeep: '#4E7FB8',
  /** The aurora scarf, at both ends of its wash. */
  auroraLight: '#7EC8A9',
  auroraDark: '#9A7FD1',
  /** A small warmth the pet earned: the mug. */
  warmAccent: '#E07A2B',
  /** The bed the pet naps in. */
  bed: '#FFF6E6',
} as const;

/**
 * The order the art is drawn in.
 *
 * The tail is behind the body, the scarf has a piece in front of the body and
 * a piece behind it, and the accessories sit on top of everything. There is
 * no separate outline layer: the ink ring is woven into the cells of each
 * part, in the same fill as the part itself.
 */
export const ART_LAYERS = [
  'ground',
  'tail',
  'body',
  'scarfBack',
  'head',
  'face',
  'scarfFront',
  'accessory',
  'effects',
] as const;

export type ArtLayer = (typeof ART_LAYERS)[number];
